  source_number_phone: $json.source_number_phone || $('WABA Autocom1').item.json.source_number_phone,
};

const catalogFromMcp = Array.isArray($json.results) ? $json.results.map((item) => ({
  id: String(item.id || item.name || 'modelo').toLowerCase().replace(/\s+/g, '_'),
  segment: item.segment || 'all',
  title: item.name || 'Modelo Autocom',
  year: String(item.year || '2026'),
