})) : [];

const catalog = catalogFromMcp; const mcpReturnedNoResults = Array.isArray($json.results) && $json.results.length === 0 && Boolean($('Intent Resolver').item.json.intent_resolver?.catalog_query);

let metaPayload = null;
let internalNote = '';
let conversationUpdatePayload = {};

if (route === 'send_personal_flow') {
  const personalHeader = isEarlyPersonalFlow ? 'Atencion personalizada' : 'Datos personales';
  const personalBody = isEarlyPersonalFlow
    ? 'Para atenderte mas rapido y recomendarte el Autocom ideal, completa este formulario corto. Al continuar con esta conversacion, aceptas nuestros terminos: https://bit.ly/418l9x2'
    : 'Para continuar con tu solicitud, por favor comparte tus datos.';
  const personalCta = isEarlyPersonalFlow ? 'Completar formulario' : 'Completar datos';
  metaPayload = {
    messaging_product: 'whatsapp', recipient_type: 'individual', to: metaContext.source_number_phone, type: 'interactive',
    interactive: { type: 'flow', header: { type: 'text', text: personalHeader }, body: { text: personalBody }, footer: { text: 'Autocom Ecuador' }, action: { name: 'flow', parameters: { flow_message_version: '3', flow_token: 'flow-data-' + metaContext.source_number_phone, flow_id: metaContext.meta_personal_flow_id, flow_cta: personalCta, flow_action: 'navigate', flow_action_payload: { screen: 'SCREEN_DATOS', data: { name: contact.name || '', identifier: contact.identifier || '', email: contact.email || '', phone_number: contact.phone_number || metaContext.source_number_phone } } } } }
  };
  internalNote = isEarlyPersonalFlow
    ? 'Se envio WhatsApp Flow temprano con mensaje hibrido de terminos y captacion de datos personales.'
    : 'Se envio WhatsApp Flow de datos personales para continuar el proceso de agendamiento.';
  conversationUpdatePayload = {
