  internalNote = 'Se envio solicitud de ubicacion por WhatsApp para resolver establecimiento.';
  conversationUpdatePayload = { ...baseConversationUpdatePayload, booking_intent: $('Conversation Router').item.json.booking_state?.booking_intent || 'dealership_info', booking_location_request_sent_at: now, booking_location_request_pending: true };
} else if (route === 'send_phase6_flow') {
  metaPayload = { messaging_product: 'whatsapp', recipient_type: 'individual', to: $('WABA Autocom1').item.json.source_number_phone, type: 'interactive', interactive: { type: 'flow', header: { type: 'text', text: 'Agenda tu visita' }, body: { text: 'Completa fecha, hora y tiempo estimado de compra para avanzar con tu prueba de manejo.' }, footer: { text: 'Autocom Ecuador' }, action: { name: 'flow', parameters: { flow_message_version: '3', flow_token: 'flow-phase6-' + metaContext.source_number_phone, flow_id: metaContext.meta_phase6_flow_id, flow_cta: 'Elegir horario', flow_action: 'navigate' } } } };
