    metaPayload = { messaging_product: 'whatsapp', recipient_type: 'individual', to: $('WABA Autocom1').item.json.source_number_phone, type: 'text', text: { body: 'No encontré modelos Autocom que coincidan con esa búsqueda en este momento.' } };
