  const cards = filtered.slice(0, 10).map((item, index) => {
    const slug = String(item.title || item.id || 'modelo').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '') || String(item.id || 'modelo');
