    };
  });
  metaPayload = { messaging_product: 'whatsapp', recipient_type: 'individual', to: $('WABA Autocom1').item.json.source_number_phone, type: 'interactive', interactive: { type: 'carousel', body: { text: segment === 'suv' ? 'Estos son algunos SUV Autocom disponibles.' : segment === 'sedan' ? 'Estos son algunos sedan Autocom disponibles.' : 'Estos son algunos modelos Autocom disponibles.' }, action: { cards } } };
  internalNote = 'Se envio carrusel dinamico con quick replies de modelos Autocom (' + segment + ').';
  conversationUpdatePayload = { ...baseConversationUpdatePayload, booking_last_catalog_segment: segment, booking_last_catalog_sent_at: now, booking_last_catalog_mode: 'quick_reply' };
  }
}

return [{ json: { ...$json, meta_payload: metaPayload, internal_note_payload: { content: internalNote }, conversation_update_payload: conversationUpdatePayload } }];

