const base = $('If Establishment Options').item.json;
const data = $json || {};
const city = data.selected_city || base.booking_state?.effective_contact?.city || 'tu ciudad';
const previousAttrs = base.conversation?.custom_attributes || {};
const previousRepeatCount = Number(base.mcp_booking_state?.establishment_prompt_repeat_count ?? previousAttrs.establishment_prompt_repeat_count ?? 0) || 0;
const previousType = String(base.mcp_booking_state?.establishment_prompt_type || previousAttrs.establishment_prompt_type || '');
const previousHash = String(base.mcp_booking_state?.establishment_prompt_hash || previousAttrs.establishment_prompt_hash || '');
const isWhatsapp = Boolean(base.booking_state?.is_whatsapp);
const zoneOptions = Array.isArray(data.zones) ? data.zones.map((zone, index) => ({
  option: index + 1,
  zone: String(zone || '').trim(),
  name: String(zone || '').trim(),
  row_id: 'zone__' + String(zone || '').trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, ''),
  title: String(zone || '').trim(),
  description: city,
})) : [];
const promptHash = 'zones:' + city + ':' + zoneOptions.map((zone) => zone.zone.toLowerCase()).join('|');
const repeatCount = previousType === 'zones' && previousHash === promptHash ? previousRepeatCount + 1 : 1;
const update = {};
if (data.selected_establishment_name) update.selected_establishment_name = data.selected_establishment_name;
if (data.selected_establishment_id) update.selected_establishment_id = data.selected_establishment_id;
if (data.selected_city) update.selected_city = data.selected_city;
if (data.selected_zone) update.selected_zone = data.selected_zone;
update.establishment_question_pending = true;
update.establishment_zone_options = zoneOptions;
update.establishment_prompt_type = 'zones';
update.establishment_prompt_hash = promptHash;
update.establishment_prompt_repeat_count = repeatCount;
update.establishment_last_prompt_at = new Date().toISOString();
const defaultText = 'En ' + city + ' manejamos estas zonas disponibles: ' + data.zones.join(', ') + '. Cual prefieres para recomendarte el concesionario mas conveniente?';
const escalatedText = 'Todavia necesito definir la zona para recomendarte un concesionario. Responde solo con una de estas zonas: ' + data.zones.join(', ') + '.';
const shouldSendInteractive = isWhatsapp && zoneOptions.length >= 2 && zoneOptions.length <= 10;
return [{
  json: {
    ...base,
    force_route: shouldSendInteractive ? 'send_establishment_zone_list' : null,
    establishment_list_options: zoneOptions,
    output: {
      reply: {
        text: repeatCount >= 2 ? escalatedText : defaultText,
        channel_hints: { attachments: [] },
      },
    },
    establishment_resolution: data,
    conversation_update_payload: {
      ...(base.conversation_update_payload || {}),
      ...update,
    },
  },
}];

const base = $('If Establishment Options').item.json;
const data = $json || {};
const city = data.selected_city || base.booking_state?.effective_contact?.city || 'tu ciudad';
const previousAttrs = base.conversation?.custom_attributes || {};
const previousRepeatCount = Number(base.mcp_booking_state?.establishment_prompt_repeat_count ?? previousAttrs.establishment_prompt_repeat_count ?? 0) || 0;
