const isWhatsapp = Boolean(base.booking_state?.is_whatsapp);
const candidateOptions = Array.isArray(data.candidates) ? data.candidates.slice(0, 10).map((candidate, index) => ({
  option: index + 1,
  id: candidate.id,
  name: candidate.name,
  address: candidate.address || '',
  city: candidate.city || '',
  zone: candidate.zone || '',
  row_id: 'est__' + String(candidate.id || index + 1),
  title: candidate.name,
  description: candidate.address || candidate.city || '',
})) : [];
const promptHash = 'candidates:' + city + ':' + candidateOptions.map((candidate) => String(candidate.name || '').trim().toLowerCase()).join('|');
const repeatCount = previousType === 'candidates' && previousHash === promptHash ? previousRepeatCount + 1 : 1;
const update = {};
if (data.selected_establishment_name) update.selected_establishment_name = data.selected_establishment_name;
if (data.selected_establishment_id) update.selected_establishment_id = data.selected_establishment_id;
