update.establishment_prompt_type = 'candidates';
update.establishment_prompt_hash = promptHash;
update.establishment_prompt_repeat_count = repeatCount;
update.establishment_last_prompt_at = new Date().toISOString();
const list = candidateOptions
  .map((candidate) => candidate.option + '. ' + candidate.name + ' - ' + (candidate.address || candidate.city || ''))
  .join('\n');
