const shouldSendInteractive = isWhatsapp && candidateOptions.length >= 2 && candidateOptions.length <= 10;
return [{
  json: {
    ...base,
    force_route: shouldSendInteractive ? 'send_establishment_candidate_list' : null,
    establishment_list_options: candidateOptions,
    output: {
      reply: {
        text: repeatCount >= 2 ? escalatedText : defaultText,
        channel_hints: { attachments: [] },
      },
    },
    establishment_resolution: data,
    conversation_update_payload: {
      ...(base.conversation_update_payload || {}),
      ...update,
    },
  },
}];

